class OnlineCache:
    def __init__(self):
        self.store = {}
    def get(self, entity):
        return self.store.get(entity, None)
    def update(self, entity, value):
        self.store[entity] = value

# populate from offline DataFrame df_offline with columns (entity, as_of, val)
cache = OnlineCache()
latest = df_offline.sort_values('as_of').groupby('entity').tail(1)
for _, row in latest.iterrows():
    cache.update(row['entity'], row['val'])
# Now cache.get(42) returns the most recent value for entity 42.
